"""Evaluate frozen sector trend detection and dynamic ETF execution."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import numpy as np,pandas as pd
BUY_COST=.0015;SELL_COST=.0015;SEED=20260830
def encode(value):return value.item() if hasattr(value,"item") else str(value)
def bootstrap(values,reps=10000):
 x=np.asarray(values,float);rng=np.random.default_rng(SEED);means=[rng.choice(x,len(x),replace=True).mean() for _ in range(reps)];return np.quantile(means,[.025,.975]).tolist()
def detection_summary(labels,positions):
 labels=labels.copy();labels["year"]=labels.trend_start.dt.year;historical=labels[labels.year.between(2018,2025)];position_year=positions.entry_signal_date.dt.year;historical_positions=positions[position_year.between(2018,2025)];matched=set(historical.position_id[historical.detected&historical.position_id.notna()]);periods={}
 for name,a,b in [("2018-2022",2018,2022),("2023-2024",2023,2024),("2025",2025,2025),("2026",2026,2026)]:
  g=labels[labels.year.between(a,b)];periods[name]={"count":len(g),"recall":float(g.detected.mean()) if len(g) else 0.0,"median_delay":float(g.loc[g.detected,"detection_delay"].median()) if g.detected.any() else None,"median_capture_ratio":float(g.loc[g.detected,"capture_ratio"].median()) if g.detected.any() else None}
 false_rate=float((~historical_positions.position_id.isin(matched)).mean()) if len(historical_positions) else 1.0;summary={"trend_labels":len(historical),"detected":int(historical.detected.sum()),"recall":float(historical.detected.mean()),"median_delay":float(historical.loc[historical.detected,"detection_delay"].median()),"median_capture_ratio":float(historical.loc[historical.detected,"capture_ratio"].median()),"signals":len(historical_positions),"false_positive_rate":false_rate,"periods":periods};checks={"count":len(historical)>=30,"recall":summary["recall"]>=.60,"validation_recall":periods["2023-2024"]["recall"]>=.50,"holdout_recall":periods["2025"]["recall"]>=.50,"delay":summary["median_delay"]<=7,"capture":summary["median_capture_ratio"]>=.50,"false_positive":false_rate<=.50};return summary,checks
def select_etf(signal,sector,candidates,prices_by_code):
 pool=candidates[(candidates.industry==sector)&(candidates.list_date<=signal)&(candidates.delist_date.isna()|(candidates.delist_date>=signal))];choice=None;best=-np.inf
 for code in pool.ts_code.unique():
  price=prices_by_code.get(code)
  if price is None:continue
  history=price[price.index<signal].tail(20)
  if len(history)>=10 and float(history.amount.mean())>=10000 and float(history.amount.mean())>best:choice=code;best=float(history.amount.mean())
 return choice,best
def evaluate_etfs(positions,candidates_path,daily_path,adj_path,benchmark_path):
 candidates=pd.read_csv(candidates_path,dtype=str);candidates["list_date"]=pd.to_datetime(candidates.list_date,errors="coerce");candidates["delist_date"]=pd.to_datetime(candidates.delist_date,errors="coerce");daily=pd.read_parquet(daily_path);adj=pd.read_parquet(adj_path);daily.trade_date=pd.to_datetime(daily.trade_date.astype(str),format="mixed");adj.trade_date=pd.to_datetime(adj.trade_date.astype(str),format="mixed");prices=daily.merge(adj,on=["ts_code","trade_date"],how="inner");prices["adj_open"]=prices.open*prices.adj_factor;prices["adj_close"]=prices.close*prices.adj_factor;prices_by_code={code:g.set_index("trade_date").sort_index() for code,g in prices.groupby("ts_code")};benchmark=pd.read_csv(benchmark_path);benchmark=benchmark[benchmark.asset.eq("equity")].copy();benchmark.trade_date=pd.to_datetime(benchmark.trade_date,format="mixed");benchmark=benchmark.set_index("trade_date").sort_index();records=[]
 for row in positions.itertuples(index=False):
  signal=pd.Timestamp(row.entry_signal_date);choice,best=select_etf(signal,row.sector,candidates,prices_by_code);base={"position_id":row.position_id,"sector":row.sector,"signal_date":signal.date().isoformat(),"exit_signal_date":pd.Timestamp(row.exit_signal_date).date().isoformat() if pd.notna(row.exit_signal_date) else None,"exit_reason":row.exit_reason,"etf_code":choice,"status":"VALID","rejection_reason":""};future=benchmark.index[benchmark.index>signal][:40]
  if choice is None or len(future)<35:records.append({**base,"status":"INVALID","rejection_reason":"no_liquid_etf_or_horizon","observed_days":0});continue
  price=prices_by_code[choice];entry_date=future[0]
  if entry_date not in price.index or float(price.at[entry_date,"adj_open"])<=0:records.append({**base,"status":"INVALID","rejection_reason":"missing_t1_open","observed_days":0});continue
  exit_signal=pd.Timestamp(row.exit_signal_date) if pd.notna(row.exit_signal_date) else None;exit_dates=benchmark.index[benchmark.index>exit_signal] if exit_signal is not None else [];exit_date=exit_dates[0] if len(exit_dates) else None;entry=float(price.at[entry_date,"adj_open"]);bench_entry=float(benchmark.at[entry_date,"adj_open"]);returns=[];active=[];dates=[];exit_value=None
  for day in future:
   if day not in benchmark.index:break
   if exit_date is not None and day>=exit_date and exit_value is None:
    if exit_date not in price.index:break
    exit_value=float(price.at[exit_date,"adj_open"])/entry*(1-BUY_COST)*(1-SELL_COST)-1
   if exit_value is None:
    if day not in price.index:break
    value=float(price.at[day,"adj_close"])/entry*(1-BUY_COST)-1
   else:value=exit_value
   bench=float(benchmark.at[day,"adj_close"])/bench_entry-1;dates.append(day);returns.append(value);active.append(value-bench)
  def at(values,n):return float(values[n-1]) if len(values)>=n else None
  records.append({**base,"entry_date":entry_date.date().isoformat(),"exit_date":exit_date.date().isoformat() if exit_date is not None else None,"avg_amount20":best,"observed_days":len(returns),"return_d20":at(returns,20),"return_d35":at(returns,35),"active_d20":at(active,20),"active_d35":at(active,35),"max_return_35":float(max(returns)) if returns else None,"min_return_35":float(min(returns)) if returns else None,"days_outperform_35":int((np.asarray(active)>0).sum()) if active else 0,"success_d20":bool(len(returns)>=20 and returns[19]>0 and active[19]>0)})
 return pd.DataFrame(records)
def trading_summary(events):
 x=events[(events.status=="VALID")&events.active_d20.notna()&events.active_d35.notna()].copy();x["year"]=pd.to_datetime(x.signal_date).dt.year;x=x[x.year.between(2018,2025)];ci=bootstrap(x.active_d20) if len(x) else [np.nan,np.nan];cut=max(1,int(np.ceil(len(x)*.05))) if len(x) else 0;trim=x.sort_values("active_d20").iloc[:-cut].active_d20.mean() if len(x)>cut else np.nan;periods={name:{"count":len(g),"mean_active20":float(g.active_d20.mean()) if len(g) else 0.0,"success_rate":float(g.success_d20.mean()) if len(g) else 0.0} for name,a,b in [("2018-2022",2018,2022),("2023-2024",2023,2024),("2025",2025,2025)] for g in [x[x.year.between(a,b)]]};summary={"source_events":len(events),"mapped_events":int(events.etf_code.notna().sum()),"complete_events":len(x),"mapping_rate":float(events.etf_code.notna().mean()) if len(events) else 0.0,"absolute_positive20":float((x.return_d20>0).mean()) if len(x) else 0.0,"outperform20":float((x.active_d20>0).mean()) if len(x) else 0.0,"success20":float(x.success_d20.mean()) if len(x) else 0.0,"median_active20":float(x.active_d20.median()) if len(x) else 0.0,"median_active35":float(x.active_d35.median()) if len(x) else 0.0,"bootstrap95_active20":ci,"trim_best5_mean_active20":float(trim) if pd.notna(trim) else None,"periods":periods};checks={"count":len(x)>=30,"mapping":summary["mapping_rate"]>=.50,"absolute":summary["absolute_positive20"]>=.60,"outperform":summary["outperform20"]>=.60,"active20":summary["median_active20"]>0,"active35":summary["median_active35"]>0,"bootstrap":ci[0]>0,"trim":pd.notna(trim) and trim>0,"periods":all(v["mean_active20"]>0 for v in periods.values()),"holdout":periods["2025"]["count"]>=5 and periods["2025"]["success_rate"]>=.50};return summary,checks
def run(labels_path,positions_path,candidates,daily,adj,benchmark,events_path,out_json,out_md):
 labels=pd.read_csv(labels_path);labels["trend_start"]=pd.to_datetime(labels.trend_start);labels["detected"]=labels.detected.astype(str).str.lower().eq("true");positions=pd.read_csv(positions_path);positions["entry_signal_date"]=pd.to_datetime(positions.entry_signal_date);positions["exit_signal_date"]=pd.to_datetime(positions.exit_signal_date,errors="coerce");detection,dchecks=detection_summary(labels,positions);events=evaluate_etfs(positions,candidates,daily,adj,benchmark);events.to_csv(events_path,index=False);trading,tchecks=trading_summary(events);payload={"study":"a-share-sector-trend-detector-v1","authority":"exploratory_only_no_platform_prepare_operation","detection":{"summary":detection,"checks":dchecks,"verdict":"GO" if all(dchecks.values()) else "NO-GO"},"trading":{"summary":trading,"checks":tchecks,"verdict":"GO" if all(tchecks.values()) else "NO-GO"},"events":events_path};Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2,default=encode)+"\n");lines=["# A股行业趋势启动识别V1结果","",f"- detection: **{payload['detection']['verdict']}**",f"- trading: **{payload['trading']['verdict']}**",f"- trends/recall/delay/capture/false-positive: {detection['trend_labels']} / {detection['recall']:.2%} / {detection['median_delay']:.1f} / {detection['median_capture_ratio']:.2%} / {detection['false_positive_rate']:.2%}",f"- ETF complete/positive20/outperform20/median active20: {trading['complete_events']} / {trading['absolute_positive20']:.2%} / {trading['outperform20']:.2%} / {trading['median_active20']:.2%}"];Path(out_md).write_text("\n".join(lines)+"\n");print("\n".join(lines));return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--labels",default="overall/a-share-sector-month-trend-labels.csv");p.add_argument("--positions",default="overall/a-share-sector-trend-positions.csv");p.add_argument("--candidates",default="overall/a-share-sector-etf-candidates.csv");p.add_argument("--daily",default="overall/a-share-sector-etf-raw-v2/fund_daily.parquet");p.add_argument("--adj",default="overall/a-share-sector-etf-raw-v2/fund_adj.parquet");p.add_argument("--benchmark",default="overall/a-share-equity-etf-daily-current.csv");p.add_argument("--events",default="overall/a-share-sector-trend-etf-events.csv");p.add_argument("--out-json",default="overall/a-share-sector-trend-detector-result.json");p.add_argument("--out-md",default="overall/a-share-sector-trend-detector-result.md");a=p.parse_args(argv);run(a.labels,a.positions,a.candidates,a.daily,a.adj,a.benchmark,a.events,a.out_json,a.out_md);return 0
if __name__=="__main__":raise SystemExit(main())
